package local.wallpanel.app;
import java.net.*;
import java.util.*;
import java.util.concurrent.atomic.*;

/** Real SIP UDP stack against a loopback PBX; media is a fake with no microphone. */
public final class SipTests {
    private static int checks;
    private static void check(boolean value){checks++;if(!value)throw new AssertionError("SIP check "+checks);}
    private static void bad(Runnable task){boolean rejected=false;try{task.run();}catch(IllegalArgumentException e){rejected=true;}check(rejected);}
    private static void mediaTests()throws Exception{
        check(SipG711.decode((byte)255)==0);check(SipG711.decode((byte)127)==0);check(SipG711.decode((byte)128)==32124);check(SipG711.decode((byte)0)==-32124);check((SipG711.encode((short)0)&255)==255);check((SipG711.encode((short)1000)&255)==206);check((SipG711.encode((short)-1000)&255)==78);
        for(int i=0;i<256;i++)check((SipG711.encode(SipG711.decode((byte)i))&255)==(i==127?255:i));
        byte[] r=new byte[200];SipRtpPacket.header(r,0,65535,0xfffffff0L,123);r[0]=(byte)0xb2;r[23]=3;r[199]=4;SipRtpPacket p=SipRtpPacket.parse(r,200,0);check(p!=null&&p.offset==36&&p.length==160&&p.timestamp==0xfffffff0L);
        SipRtpPacket.Sequence order=new SipRtpPacket.Sequence();check(order.accept(p));check(!order.accept(p));r[2]=r[3]=0;check(order.accept(SipRtpPacket.parse(r,200,0)));r[2]=(byte)255;r[3]=(byte)254;check(!order.accept(SipRtpPacket.parse(r,200,0)));
        r[1]=101;check(SipRtpPacket.parse(r,200,0)==null);r[1]=0;r[199]=0;check(SipRtpPacket.parse(r,200,0)==null);r[199]=4;r[22]=(byte)255;check(SipRtpPacket.parse(r,200,0)==null);check(SipRtpPacket.parse(new byte[11],11,0)==null);
        String text="v=0\r\nc=IN IP4 127.0.0.1\r\nm=video 30002 RTP/AVP 96\r\na=rtpmap:96 H264/90000\r\nm=audio 30000 RTP/AVP 101 97\r\na=rtpmap:101 telephone-event/8000\r\na=rtpmap:97 PCMU/8000\r\nc=IN IP4 127.0.0.2\r\n";
        SipSdp offer=SipSdp.parse(text);check(offer.payloadType==97&&offer.remotePort==30000&&offer.remoteAddress.equals("127.0.0.2"));String answer=offer.answer("127.0.0.1",10000);check(answer.indexOf("m=video 0")<answer.indexOf("m=audio 10000"));check(answer.contains("a=rtpmap:97 PCMU/8000"));
        bad(new Runnable(){public void run(){SipSdp.parse("v=0\r\nc=IN IP4 127.0.0.1\r\nm=audio 10000 RTP/AVP 8\r\n");}});
        check(SipDigest.response("Mufasa","testrealm@host.com","Circle Of Life","GET","/dir/index.html","dcd98b7102dd2f0e8b11d0f600bfb0c093","MD5","auth","00000001","0a4f113b").equals("6629fae49393a05397450978507c4ef1"));
        final SipConfig c=new SipConfig();c.server="127.0.0.1";c.user="1001";c.validate();check(c.ringtoneEnabled&&c.ringVolume==65&&!c.videoEnabled);c.videoUrl="rtsp://admin:p%40ss@192.0.2.1:554/Streaming/Channels/101";c.videoEnabled=true;c.validate();check(c.sameConnection(newConfig()));c.videoUrl="http://192.0.2.1/video";bad(new Runnable(){public void run(){c.validate();}});c.videoUrl="rtsp:///missing-host";bad(new Runnable(){public void run(){c.validate();}});c.videoUrl="rtsp://192.0.2.1:70000/test";bad(new Runnable(){public void run(){c.validate();}});c.videoUrl="rtsp://192.0.2.1/test";c.ringVolume=101;bad(new Runnable(){public void run(){c.validate();}});c.ringVolume=65;c.rtpPort=10001;bad(new Runnable(){public void run(){c.validate();}});
    }
    private static SipConfig newConfig(){SipConfig c=new SipConfig();c.server="127.0.0.1";c.user="1001";return c;}
    private static final class Packet {String text;InetAddress address;int port;}
    private static String h(String text,String name){for(String line:text.split("\r?\n"))if(line.regionMatches(true,0,name+":",0,name.length()+1))return line.substring(name.length()+1).trim();return "";}
    private static final class Pbx implements java.io.Closeable {
        DatagramSocket socket;int client;
        Pbx()throws Exception{socket=new DatagramSocket(0,InetAddress.getByName("127.0.0.1"));socket.setSoTimeout(250);}
        Packet waitFor(String first,String method,String call)throws Exception{long end=System.currentTimeMillis()+7000;while(System.currentTimeMillis()<end){byte[] b=new byte[65536];DatagramPacket p=new DatagramPacket(b,b.length);try{socket.receive(p);}catch(SocketTimeoutException e){continue;}Packet result=new Packet();result.text=new String(b,0,p.getLength(),"UTF-8");result.address=p.getAddress();result.port=p.getPort();if(result.text.startsWith(first)&&h(result.text,"CSeq").endsWith(method)&&(call==null||h(result.text,"Call-ID").equals(call)))return result;}throw new AssertionError("PBX timeout: "+first+" "+method);}
        void send(String text,int port)throws Exception{byte[] b=text.getBytes("UTF-8");socket.send(new DatagramPacket(b,b.length,InetAddress.getByName("127.0.0.1"),port));}
        void response(Packet request,int code,String extra)throws Exception{StringBuilder s=new StringBuilder("SIP/2.0 "+code+" Test\r\n");for(String key:new String[]{"Via","From","To","Call-ID","CSeq"})s.append(key).append(": ").append(h(request.text,key)).append(key.equals("To")&&!h(request.text,key).contains(";tag=")?";tag=pbx":"").append("\r\n");s.append(extra).append("Content-Length: 0\r\n\r\n");send(s.toString(),request.port);}
        String request(String method,String id,String branch,String to,int cseq,String body){return method+" sip:1001@127.0.0.1:"+client+" SIP/2.0\r\nVia: SIP/2.0/UDP 127.0.0.1:"+socket.getLocalPort()+";branch="+branch+";rport\r\nMax-Forwards: 70\r\nFrom: Door <sip:door@127.0.0.1>;tag=door1\r\nTo: "+to+"\r\nCall-ID: "+id+"\r\nCSeq: "+cseq+" "+method+"\r\nContact: <sip:door@127.0.0.1:"+socket.getLocalPort()+">\r\n"+(body.length()>0?"Content-Type: application/sdp\r\n":"")+"Content-Length: "+body.length()+"\r\n\r\n"+body;}
        public void close(){socket.close();}
    }
    private static void state(SipEngine engine,SipEngine.State expected)throws Exception{long until=System.currentTimeMillis()+5000;while(engine.state()!=expected&&System.currentTimeMillis()<until)Thread.sleep(10);check(engine.state()==expected);}
    private static String sdp(int port){return "v=0\r\no=door 1 1 IN IP4 127.0.0.1\r\ns=Test\r\nc=IN IP4 127.0.0.1\r\nt=0 0\r\nm=audio "+port+" RTP/AVP 0 101\r\na=rtpmap:0 PCMU/8000\r\na=rtpmap:101 telephone-event/8000\r\n";}
    private static void engineTests()throws Exception{
        final AtomicInteger starts=new AtomicInteger(),stops=new AtomicInteger(),updates=new AtomicInteger();final SipConfig config=new SipConfig();config.server="127.0.0.1";config.localAddress="127.0.0.1";config.user="1001";config.password="local-test-only";
        DatagramSocket port=new DatagramSocket(0);config.sipPort=port.getLocalPort();port.close();final Pbx pbx=new Pbx();config.serverPort=pbx.socket.getLocalPort();pbx.client=config.sipPort;
        final SipEngine engine=new SipEngine(new SipEngine.Host(){public SipConfig settings(){return config;}public void state(SipEngine.State state,boolean registered,String caller,String detail){}public SipEngine.Media media(String local,SipConfig c){return new SipEngine.Media(){boolean open;public void start(SipSdp offer){open=true;starts.incrementAndGet();}public void update(SipSdp offer){updates.incrementAndGet();}public void close(){if(open){open=false;stops.incrementAndGet();}}};}});
        try{engine.start();Packet first=pbx.waitFor("REGISTER ","REGISTER",null);pbx.response(first,401,"WWW-Authenticate: Digest realm=\"unit\", nonce=\"abcdef\", algorithm=MD5, qop=\"auth\"\r\n");Packet auth=pbx.waitFor("REGISTER ","REGISTER",null);check(h(auth.text,"Call-ID").equals(h(first.text,"Call-ID")));check(h(auth.text,"CSeq").startsWith("2 "));check(h(auth.text,"Authorization").contains("qop=auth"));pbx.response(auth,200,"Contact: "+h(auth.text,"Contact")+";expires=3600\r\n");long until=System.currentTimeMillis()+3000;while(!engine.registered()&&System.currentTimeMillis()<until)Thread.sleep(10);check(engine.registered());
            String to="<sip:1001@127.0.0.1>";pbx.send(pbx.request("INVITE","call-a","z9hG4bKcalla",to,1,sdp(30000)),pbx.client);Packet ringing=pbx.waitFor("SIP/2.0 180","INVITE","call-a");state(engine,SipEngine.State.RINGING);check(starts.get()==0);
            pbx.send(pbx.request("INVITE","busy","z9hG4bKbusy",to,1,sdp(30000)),pbx.client);pbx.waitFor("SIP/2.0 486","INVITE","busy");engine.answer();Packet ok=pbx.waitFor("SIP/2.0 200","INVITE","call-a");check(h(ok.text,"To").equals(h(ringing.text,"To")));check(ok.text.contains("PCMU/8000"));state(engine,SipEngine.State.IN_CALL);check(starts.get()==1);
            pbx.send(pbx.request("ACK","call-a","z9hG4bKacka",h(ok.text,"To"),1,""),pbx.client);
            pbx.send(pbx.request("INVITE","call-a","z9hG4bKdirect",h(ok.text,"To"),2,sdp(30002)),pbx.client);Packet renegotiated=pbx.waitFor("SIP/2.0 200","INVITE","call-a");check(h(renegotiated.text,"To").equals(h(ok.text,"To")));check(updates.get()==1);pbx.send(pbx.request("ACK","call-a","z9hG4bKackb",h(ok.text,"To"),2,""),pbx.client);
            engine.hangup();Packet bye=pbx.waitFor("BYE ","BYE","call-a");pbx.response(bye,200,"");state(engine,SipEngine.State.IDLE);check(stops.get()==1);
            pbx.send(pbx.request("INVITE","cancel","z9hG4bKcancel",to,1,sdp(30000)),pbx.client);pbx.waitFor("SIP/2.0 180","INVITE","cancel");pbx.send(pbx.request("CANCEL","cancel","z9hG4bKcancel",to,1,""),pbx.client);pbx.waitFor("SIP/2.0 200","CANCEL","cancel");pbx.waitFor("SIP/2.0 487","INVITE","cancel");state(engine,SipEngine.State.IDLE);check(starts.get()==1);
            pbx.send(pbx.request("INVITE","decline","z9hG4bKdecline",to,1,sdp(30000)),pbx.client);pbx.waitFor("SIP/2.0 180","INVITE","decline");engine.hangup();pbx.waitFor("SIP/2.0 603","INVITE","decline");state(engine,SipEngine.State.IDLE);check(starts.get()==1);
            config.autoAnswer=true;pbx.send(pbx.request("INVITE","auto-cancel","z9hG4bKautoc",to,1,sdp(30000)),pbx.client);pbx.waitFor("SIP/2.0 180","INVITE","auto-cancel");pbx.send(pbx.request("CANCEL","auto-cancel","z9hG4bKautoc",to,1,""),pbx.client);pbx.waitFor("SIP/2.0 200","CANCEL","auto-cancel");pbx.waitFor("SIP/2.0 487","INVITE","auto-cancel");Thread.sleep(650);check(starts.get()==1&&engine.state()==SipEngine.State.IDLE);
            pbx.send(pbx.request("INVITE","auto-live","z9hG4bKautolive",to,1,sdp(30000)),pbx.client);pbx.waitFor("SIP/2.0 180","INVITE","auto-live");Packet automatic=pbx.waitFor("SIP/2.0 200","INVITE","auto-live");check(starts.get()==2);pbx.send(pbx.request("ACK","auto-live","z9hG4bKautoack",h(automatic.text,"To"),1,""),pbx.client);pbx.send(pbx.request("BYE","auto-live","z9hG4bKremotebye",h(automatic.text,"To"),2,""),pbx.client);pbx.waitFor("SIP/2.0 200","BYE","auto-live");state(engine,SipEngine.State.IDLE);check(stops.get()==2);
            pbx.send(pbx.request("INVITE","auto-off","z9hG4bKautooff",to,1,sdp(30000)),pbx.client);pbx.waitFor("SIP/2.0 180","INVITE","auto-off");config.autoAnswer=false;Thread.sleep(650);check(starts.get()==2&&engine.state()==SipEngine.State.RINGING);engine.hangup();pbx.waitFor("SIP/2.0 603","INVITE","auto-off");state(engine,SipEngine.State.IDLE);
        }finally{engine.close();pbx.close();}
    }
    public static void main(String[] args)throws Exception{mediaTests();engineTests();engineTests();Thread.sleep(2500);for(Thread t:Thread.getAllStackTraces().keySet())if(t.isAlive()&&!t.isDaemon()&&t!=Thread.currentThread())throw new AssertionError("SIP thread leaked: "+t.getName());checks++;System.out.println("PASS: "+checks+" SIP/PCMU/SDP/RTP/digest checks; loopback registration, stable tags, busy, media renegotiation, local/remote BYE, CANCEL, decline, auto-answer/live-off, restart and clean shutdown. Fake media only.");}
}
